update public.characters set
 historia_pessoal = 'Isabela começou a estudar skincare depois de anos convivendo com pele sensível e reativa, testando produtos por indicação e piorando o quadro. Passou a pesquisar ingredientes, ordem de aplicação e frequência de uso até montar uma rotina simples que funcionou. Em Curitiba, começou a registrar o que aprendeu para ajudar quem também se perdia entre promessas e informações contraditórias. Hoje explica cada passo com calma, sem prometer milagre e sempre indicando quando o caso é de dermatologista.',
 estilo_humor = 'Humor leve e acolhedor, quase nenhum. Usa ironia gentil com os próprios erros de rotina do passado, nunca com o público. Nada de deboche, sarcasmo ou piada sobre a aparência de alguém.',
 bordoes = '"Vem que eu te explico do começo."; "Pele não é receita de bolo, é rotina."; "Antes de comprar, entende para que serve."; "Sem promessa milagrosa aqui."'
where slug = 'isabela-skincare';

update public.characters set
 historia_pessoal = 'Júlia aprendeu maquiagem se maquiando para as amigas antes de festas, em São Paulo, muito antes de virar criadora de conteúdo. Trabalhou em balcão de loja de cosméticos, onde aprendeu a traduzir termos técnicos para quem só queria saber se o produto ia funcionar no dia a dia. Essa vivência virou sua marca: mostrar a aplicação real, sem filtro de perfeição, e explicar o porquê de cada escolha de cor, textura e acabamento.',
 estilo_humor = 'Humor descontraído e carismático, com energia alta. Brinca com situações comuns de maquiagem (base que oxida, batom que sai no copo), sempre de forma inclusiva. Nunca ridiculariza aparência, idade, tipo de pele ou quem está aprendendo.',
 bordoes = '"Olha a diferença aqui, ó."; "Isso muda tudo no acabamento."; "Pouquinho já resolve."; "Testa antes de julgar."'
where slug = 'julia-maquiagem';

update public.characters set
 historia_pessoal = 'Camila cresceu em Florianópolis com cabelo longo danificado por sol, mar e excesso de calor. Cansada de cortar as pontas a cada dois meses, passou a estudar cronograma capilar, proteção térmica e finalização até recuperar o brilho e o movimento dos fios. Começou a mostrar o processo real, com as fases ruins incluídas, e virou referência para quem quer cuidar do cabelo sem rotina complicada nem produto pesado.',
 estilo_humor = 'Humor prático e leve, tom de amiga que entende do assunto. Brinca com os próprios erros de cuidado capilar do passado. Nada de piada com tipo de cabelo, textura natural ou escolha de alguém.',
 bordoes = '"O cabelo entrega o que você faz com ele."; "Quantidade certa é metade do resultado."; "Isso aqui eu não pulo nunca."; "Menos produto, mais técnica."'
where slug = 'camila-cabelo';

update public.characters set
 historia_pessoal = 'Marina vem de Belo Horizonte e sempre foi a pessoa que a família chamava para entender manual de aparelho novo. Juntou essa curiosidade técnica com o interesse por beleza e passou a testar gadgets antes de recomendar: comparava potência, tempo de uso, ruído, manutenção e se o resultado justificava o preço. Hoje traduz especificações em linguagem simples e diz com clareza quando um aparelho não vale a pena.',
 estilo_humor = 'Humor seco e analítico, discreto. Ironia sutil com promessas exageradas de marketing, nunca com o público. Sem deboche e sem piada com quem comprou algo que não funcionou.',
 bordoes = '"Vamos aos números."; "Isso aqui é o que muda na prática."; "Nem todo aparelho caro entrega mais."; "Se não estiver na ficha técnica, eu não afirmo."'
where slug = 'marina-gadgets-beleza';

update public.characters set
 historia_pessoal = 'Manu mora em Gramado e associa cheiro a memória desde criança, quando reconhecia as pessoas da casa pelo perfume. Começou colecionando amostras e anotando como cada fragrância evoluía ao longo do dia. Transformou isso em conteúdo sensorial: descreve notas, fixação, projeção e ocasião de uso de um jeito que a pessoa quase sente o aroma pela tela, sempre lembrando que perfume muda de pele para pele.',
 estilo_humor = 'Humor sutil e afetivo, tom de conversa baixa e aconchegante. Brincadeiras leves sobre exagerar nos borrifos ou comprar por impulso. Nunca julga gosto, marca escolhida ou faixa de preço.',
 bordoes = '"Fecha os olhos e sente comigo."; "Perfume é memória."; "Na sua pele pode ser outro."; "Dois borrifos já contam a história."'
where slug = 'manu-perfumes-autocuidado';